-- =========================================================================
-- SIFF Refrigeración Industrial - Schema & Seed Database (Supabase PostgreSQL)
-- Organización / Cuenta: joseebernalc93-sketch
-- =========================================================================

-- 1. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. TABLA DE USUARIOS Y ROLES SIFF
CREATE TABLE IF NOT EXISTS siff_users (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('gerencia', 'bodega', 'tecnico', 'mostrador')),
  role_title TEXT NOT NULL,
  cedula TEXT NOT NULL UNIQUE,
  avatar TEXT,
  location_default TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Habilitar RLS
ALTER TABLE siff_users ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir lectura publica demo siff_users" ON siff_users FOR SELECT USING (true);
CREATE POLICY "Permitir insercion demo siff_users" ON siff_users FOR ALL USING (true);

-- Insertar roles iniciales
ON CONFLICT (id) DO NOTHING;

-- 3. TABLA DE REPUESTOS Y STOCK FÍSICO
CREATE TABLE IF NOT EXISTS siff_products (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  lot TEXT NOT NULL,
  location TEXT NOT NULL CHECK (location IN ('Bodega Central', 'Oficina Matriz')),
  stock INTEGER NOT NULL DEFAULT 0,
  min_stock INTEGER NOT NULL DEFAULT 2,
  category TEXT NOT NULL,
  brand TEXT NOT NULL,
  image_url TEXT,
  last_movement DATE DEFAULT CURRENT_DATE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE siff_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir lectura publica demo siff_products" ON siff_products FOR SELECT USING (true);
CREATE POLICY "Permitir modificacion demo siff_products" ON siff_products FOR ALL USING (true);

-- 4. TABLA DE MOVIMIENTOS (KARDEX & AUDITORIA DE SALIDAS/ENTRADAS)
CREATE TABLE IF NOT EXISTS siff_movements (
  id TEXT PRIMARY KEY DEFAULT ('mov-' || substr(md5(random()::text), 1, 8)),
  timestamp TEXT NOT NULL,
  product_code TEXT NOT NULL,
  product_name TEXT NOT NULL,
  location TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('SALIDA', 'ENTRADA')),
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  lot TEXT NOT NULL,
  reason TEXT NOT NULL,
  reference_detail TEXT,
  technician TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE siff_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir lectura publica demo siff_movements" ON siff_movements FOR SELECT USING (true);
CREATE POLICY "Permitir insercion demo siff_movements" ON siff_movements FOR INSERT WITH CHECK (true);

-- 5. TABLA DE TRASPASOS INTERNOS ENTRE BODEGAS
CREATE TABLE IF NOT EXISTS siff_transfers (
  id TEXT PRIMARY KEY DEFAULT ('trf-' || substr(md5(random()::text), 1, 6)),
  date TEXT NOT NULL,
  product_code TEXT NOT NULL,
  product_name TEXT NOT NULL,
  from_location TEXT NOT NULL,
  to_location TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  status TEXT NOT NULL CHECK (status IN ('EN TRÁNSITO', 'RECIBIDO')),
  requested_by TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE siff_transfers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir lectura publica demo siff_transfers" ON siff_transfers FOR SELECT USING (true);
CREATE POLICY "Permitir modificacion demo siff_transfers" ON siff_transfers FOR ALL USING (true);

-- 6. CARGA DE 357 REPUESTOS REALES DE SIFF
ON CONFLICT (id) DO UPDATE SET
  stock = EXCLUDED.stock,
  lot = EXCLUDED.lot,
  location = EXCLUDED.location;

-- 7. CARGA DE MOVIMIENTOS Y TRASPASOS INICIALES
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;
